"use client";

import { useRef, useState, type CSSProperties, type FormEvent } from "react";
import { authenticate, errorCatalog, returnPath, SESSION_KEY, tokens, type ErrorCode } from "@/lib/sbx-b2b-login";

const t = tokens;
const emailMessage = "Ingresa un correo electrónico válido. Ejemplo: usuario@empresa.com";
const passwordMessage = "Ingresa tu contraseña.";

function validEmail(emailValue: string): boolean {
  const email = emailValue.trim();
  if (!email || email.length > 254 || /\s/.test(email) || email.includes("..")) return false;
  const parts = email.split("@");
  if (parts.length !== 2 || !parts[0] || parts[0].startsWith(".") || parts[0].endsWith(".")) return false;
  const labels = parts[1].split(".");
  return labels.length >= 2 && labels.every((label) => Boolean(label) && !label.startsWith("-") && !label.endsWith("-"));
}

type IconName = "Mail" | "LockKeyhole" | "Eye" | "EyeOff";
function Icon({ name }: { name: IconName }) {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      {name === "Mail" && <><rect x="2" y="4" width="20" height="16" rx="2" /><path d="m22 7-10 6L2 7" /></>}
      {name === "LockKeyhole" && <><rect x="4" y="10" width="16" height="12" rx="2" /><path d="M8 10V7a4 4 0 0 1 8 0v3M12 15v2" /></>}
      {name === "Eye" && <><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z" /><circle cx="12" cy="12" r="3" /></>}
      {name === "EyeOff" && <><path d="m3 3 18 18M10.6 5.1A11 11 0 0 1 12 5c6 0 10 7 10 7a14 14 0 0 1-3 3.7M6.3 6.3C3.6 8.2 2 12 2 12s4 7 10 7c1.2 0 2.4-.3 3.5-.8" /></>}
    </svg>
  );
}
const inputStyle: CSSProperties = {
  boxSizing: "border-box", width: "100%", background: t.card_surface, color: t.navy_core,
  border: `1px solid ${t.border_soft}`, borderRadius: t.radius_12,
  padding: `${t.space_16} ${t.space_48}`, font: "inherit",
};
const linkStyle: CSSProperties = {
  color: t.blue_brand_accent, textDecoration: "underline", ...t.text_body_small,
};

export default function SbxB2bLoginPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [visible, setVisible] = useState(false);
  const [pending, setPending] = useState(false);
  const [emailError, setEmailError] = useState(false);
  const [passwordError, setPasswordError] = useState(false);
  const [error, setError] = useState<{ code: ErrorCode; correlationId?: string } | null>(null);
  const inFlight = useRef(false);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (inFlight.current) return;
    const badEmail = !validEmail(email);
    const badPassword = password.length === 0;
    setEmailError(badEmail);
    setPasswordError(badPassword);
    setError(null);
    if (badEmail || badPassword) return;
    inFlight.current = true;
    setPending(true);
    try {
      const result = await authenticate(email.trim(), password);
      if (result.ok) {
        window.sessionStorage.setItem(SESSION_KEY, result.success.token);
        window.location.assign(returnPath(window.location.search));
      } else {
        setError({ code: result.code, correlationId: result.correlationId });
      }
    } finally {
      setPending(false);
      inFlight.current = false;
    }
  }

  const currentError = error ? errorCatalog[error.code] : null;
  return (
    <main style={{ minHeight: "100dvh", display: "flex", flexDirection: "column", boxSizing: "border-box",
      background: t.warm_surface, color: t.navy_core, fontFamily: t.font_family_base, padding: t.space_24 }}>
      <style>{`
        .sbx-b2b-shell { container-type: inline-size; flex: 1; display: grid; place-items: center; }
        .sbx-b2b-form { width: 100%; max-width: calc(${t.space_64} * 8); }
        .sbx-b2b-focus:focus-visible { outline: 3px solid ${t.blue_brand_accent}; outline-offset: ${t.space_4}; }
        .sbx-b2b-submit:hover:not(:disabled) { background: ${t.green_action_hover} !important; }
        .sbx-b2b-submit:disabled { opacity: .7; cursor: wait; }
        @container (max-width: 480px) { .sbx-b2b-form { max-width: 100%; } }
        @media (forced-colors: active) {
          .sbx-b2b-focus:focus-visible { outline-color: Highlight; }
          .sbx-b2b-submit, .sbx-b2b-field { border: 1px solid ButtonText !important; }
        }
        @media (prefers-reduced-motion: reduce) {
          .sbx-b2b-form * { transition: none !important; animation: none !important; }
        }
      `}</style>
      <header style={{ display: "flex", justifyContent: "flex-end", paddingBottom: t.space_24 }}>
        <strong style={{ textAlign: "right" }}>Backoffice Empresa</strong>
      </header>
      <section className="sbx-b2b-shell" aria-label="Iniciar sesión">
        <form className="sbx-b2b-form" onSubmit={(event) => void submit(event)} noValidate>
          <h1 style={{ ...t.text_section_h2, margin: `0 0 ${t.space_32}` }}>Iniciar sesión</h1>
          <div style={{ marginBottom: t.space_24 }}>
            <label htmlFor="sbx-email" style={{ display: "block", marginBottom: t.space_8, ...t.text_body_small }}>
              Correo electrónico
            </label>
            <div style={{ position: "relative" }}>
              <span aria-hidden="true" style={{ position: "absolute", left: t.space_16, top: t.space_16, color: t.navy_muted }}>
                <Icon name="Mail" />
              </span>
              <input className="sbx-b2b-field sbx-b2b-focus" id="sbx-email" type="email" name="email"
                autoComplete="username" placeholder="ejemplo@empresa.com" maxLength={254} required
                value={email} aria-invalid={emailError} aria-describedby={emailError ? "sbx-email-error" : undefined}
                onChange={(event) => { setEmail(event.target.value); setEmailError(false); }} style={inputStyle} />
            </div>
            {emailError && <p role="alert" id="sbx-email-error" style={{ color: t.error_text, ...t.text_body_small }}>{emailMessage}</p>}
          </div>
          <div>
            <label htmlFor="sbx-password" style={{ display: "block", marginBottom: t.space_8, ...t.text_body_small }}>
              Contraseña
            </label>
            <div style={{ position: "relative" }}>
              <span aria-hidden="true" style={{ position: "absolute", top: t.space_16, left: t.space_16, color: t.navy_muted }}>
                <Icon name="LockKeyhole" />
              </span>
              <input className="sbx-b2b-field sbx-b2b-focus" id="sbx-password" name="password" required
                type={visible ? "text" : "password"} autoComplete="current-password"
                placeholder="Ingresa tu contraseña" value={password}
                aria-invalid={passwordError} aria-describedby={passwordError ? "sbx-password-error" : undefined}
                onChange={(event) => { setPassword(event.target.value); setPasswordError(false); }} style={inputStyle} />
              <button type="button" className="sbx-b2b-focus" aria-label={visible ? "Ocultar contraseña" : "Mostrar contraseña"}
                aria-pressed={visible} onClick={() => setVisible((wasVisible) => !wasVisible)}
                style={{ position: "absolute", right: t.space_8, top: t.space_4, minHeight: t.space_48, minWidth: t.space_48,
                  background: "transparent", border: 0, color: t.navy_muted, cursor: "pointer" }}>
                <Icon name={visible ? "EyeOff" : "Eye"} />
              </button>
            </div>
            {passwordError && <p role="alert" id="sbx-password-error" style={{ color: t.error_text, ...t.text_body_small }}>{passwordMessage}</p>}
            <div style={{ marginTop: t.space_12, textAlign: "right" }}>
              <a className="sbx-b2b-focus" href="#" style={linkStyle} onClick={(event) => event.preventDefault()}>
                ¿Olvidaste tu contraseña?
              </a>
            </div>
          </div>
          {currentError && <div role="alert" style={{ background: t.error_bg, color: t.error_text,
            borderRadius: t.radius_12, padding: t.space_16, marginTop: t.space_24 }}>
            <strong>{currentError.title}</strong>
            <p>{currentError.message}</p>
            <p>{currentError.suggestedAction}</p>
            <p>{currentError.actionLabel}{error?.correlationId ? ` · ${error.correlationId}` : ""}</p>
          </div>}
          <button className="sbx-b2b-submit sbx-b2b-focus" type="submit" disabled={pending} aria-busy={pending}
            style={{ display: "block", width: "100%", marginTop: t.space_24, padding: t.space_16,
              border: 0, borderRadius: t.radius_12, background: t.green_action,
              color: t.card_surface, cursor: "pointer", ...t.text_button }}>
            Acceder
          </button>
          <span role="status" aria-live="polite" style={{ ...t.text_body_small, color: t.navy_muted }}>
            {pending ? "Acceder" : ""}
          </span>
        </form>
      </section>
      <footer style={{ display: "flex", justifyContent: "center", flexWrap: "wrap", gap: t.space_24, paddingTop: t.space_32 }}>
        {["Términos y condiciones", "Política de privacidad", "Contáctanos"].map((label) => (
          <a className="sbx-b2b-focus" key={label} href="#" style={linkStyle}
            onClick={(event) => event.preventDefault()}>{label}</a>
        ))}
      </footer>
    </main>
  );
}

"use client";

import { useEffect, useState } from "react";
import {
  listReminders,
  type Reminder,
  type ReminderPriority,
} from "@/lib/sbx-rem-list";

const LOGIN_PATH = "/sbx-b2b-login?next=/sbx-rem-list";

export default function SbxRemListPage() {
  const [query, setQuery] = useState("");
  const [priority, setPriority] = useState<ReminderPriority | "">("");
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  useEffect(() => {
    let active = true;
    void listReminders(query, priority || undefined)
      .then((result) => {
        if (!active) return;
        if (result.status === 401) {
          window.location.assign(LOGIN_PATH);
          return;
        }
        if (result.status !== 200) {
          setReminders([]);
          setError(true);
          return;
        }
        setReminders(result.reminders);
        setError(false);
      })
      .catch(() => {
        if (!active) return;
        setReminders([]);
        setError(true);
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, [query, priority]);

  return (
    <main>
      <h1>Recordatorios</h1>
      <section aria-label="Filtros de recordatorios">
        <label htmlFor="reminder-search">Buscar</label>
        <input
          id="reminder-search"
          type="search"
          value={query}
          onChange={(event) => {
            setLoading(true);
            setQuery(event.target.value);
          }}
        />
        <label htmlFor="reminder-priority">Prioridad</label>
        <select
          id="reminder-priority"
          value={priority}
          onChange={(event) => {
            setLoading(true);
            setPriority(event.target.value as ReminderPriority | "");
          }}
        >
          <option value="">Todas</option>
          <option value="HIGH">Alta</option>
          <option value="MEDIUM">Media</option>
          <option value="LOW">Baja</option>
        </select>
      </section>
      {loading && <p role="status">Cargando recordatorios...</p>}
      {error && <p role="alert">SBX-E-GENERIC</p>}
      {!loading && !error && (
        <ul aria-label="Lista de recordatorios">
          {reminders.map((reminder) => (
            <li key={reminder.id}>
              <span>{reminder.text}</span>{" "}
              <time>{reminder.at}</time>{" "}
              <span>{reminder.priority}</span>
            </li>
          ))}
        </ul>
      )}
    </main>
  );
}

import createClient from "openapi-fetch";
import type { components, paths } from "@/lib/api/generated/sbx-b2b-login";

export const LOGIN_ROUTE = "/sbx-b2b-login";
export const REMINDERS_ROUTE = "/sbx-rem-list";
export const SESSION_KEY = "sbx-session-token";
const api = createClient<paths>({ baseUrl: process.env.NEXT_PUBLIC_API_BASE_URL ?? "" });

export const tokens = {
  navy_core: "#0F172A",
  navy_muted: "#334155",
  warm_surface: "#FDFCFA",
  card_surface: "#FFFFFF",
  border_soft: "#E2E8F0",
  error_bg: "#FEE2E2",
  error_text: "#991B1B",
  green_action: "#109044",
  green_action_hover: "#0d7336",
  blue_brand_accent: "#2563EB",
  space_4: "4px",
  space_8: "8px",
  space_12: "12px",
  space_16: "16px",
  space_24: "24px",
  space_32: "32px",
  space_48: "48px",
  space_64: "64px",
  radius_12: "12px",
  radius_16: "16px",
  radius_24: "24px",
  text_section_h2: { fontSize: "32px", lineHeight: "40px", fontWeight: 700 },
  text_body: { fontSize: "16px", lineHeight: "24px" },
  text_body_small: { fontSize: "14px", lineHeight: "20px" },
  text_button: { fontSize: "14px", lineHeight: "20px", fontWeight: 700 },
  font_family_base: "Inter, sans-serif",
} as const;

export const errorCatalog = {
  "SBX-B2B-E-CREDENTIALS": {
    title: "No pudimos iniciar sesión",
    message: "No pudimos validar tus datos de acceso. Revisa la información e inténtalo nuevamente.",
    suggestedAction: "Verifica tu correo y contraseña. Si no recuerdas tu contraseña, utiliza la opción de recuperación.",
    actionLabel: "Revisar datos",
  },
  "SBX-B2B-E-RATE": {
    title: "Demasiadas solicitudes",
    message: "Se alcanzó temporalmente el límite de operaciones.",
    suggestedAction: "Espere unos minutos antes de volver a intentar.",
    actionLabel: "Reintentar después",
  },
  "SBX-B2B-E-NETWORK": {
    title: "Conexión interrumpida",
    message: "Se perdió la conexión durante la operación.",
    suggestedAction: "Verifique su conexión. La aplicación intentará recuperar el estado.",
    actionLabel: "Reintentar",
  },
  "SBX-B2B-E-UNEXPECTED": {
    title: "No pudimos completar la operación",
    message: "Ocurrió un error inesperado.",
    suggestedAction: "Use el código de referencia para solicitar soporte.",
    actionLabel: "Contactar soporte",
  },
} as const;
export type ErrorCode = keyof typeof errorCatalog;
type Failure = components["schemas"]["LoginFailure"];
type Success = components["schemas"]["LoginSuccess"];
export type Result = { ok: true; success: Success } | { ok: false; code: ErrorCode; correlationId?: string };

function known(code: unknown): code is ErrorCode {
  return typeof code === "string" && Object.prototype.hasOwnProperty.call(errorCatalog, code);
}
export async function authenticate(email: string, password: string): Promise<Result> {
  try {
    const { response, data, error } = await api.POST("/api/auth/login", { body: { email, password } });
    if (response.status === 200 && data?.outcome === "AUTHENTICATED" && data.token) {
      return { ok: true, success: data };
    }
    const failure = error as Failure | undefined;
    const fallback: ErrorCode = response.status === 401
      ? "SBX-B2B-E-CREDENTIALS"
      : response.status === 429
        ? "SBX-B2B-E-RATE"
        : response.status === 503
          ? "SBX-B2B-E-NETWORK"
          : "SBX-B2B-E-UNEXPECTED";
    return { ok: false, code: known(failure?.error_code) ? failure.error_code : fallback, correlationId: failure?.correlation_id };
  } catch {
    return { ok: false, code: "SBX-B2B-E-NETWORK" };
  }
}
export function returnPath(search: string): string {
  const next = new URLSearchParams(search).get("next");
  return next && next.startsWith("/") && !next.startsWith("//") && !next.includes("\\") && !/[\r\n]/.test(next)
    ? next : REMINDERS_ROUTE;
}

#!/usr/bin/env python3
"""T5 trusted Worker browser acceptance: local backend + frontend + Chromium.

This is an ordinary AcceptanceCommand, so the existing verified Worker
runs it for either visible commands or an independent encrypted oracle.
No examiner material is read here. No model and no external browser traffic.
"""
from __future__ import annotations
import sys as _project_sys
from pathlib import Path as _project_Path
_project_sys.path.insert(0, str(_project_Path(__file__).resolve().parents[2]))

import argparse
import json
import re
import ipaddress
import os
from pathlib import Path
import signal
import socket
import subprocess
import sys
import time
from urllib.parse import urlparse

# Fixed toolchain pin: installed only by trusted Worker CI, never by proposals.
PLAYWRIGHT_VERSION = "1.56.0"
BROWSERS_DIR = "/tmp/lf-playwright-browsers"
PYTHON_RUNTIME = Path("/tmp/lf-python-runtime/bin/python")
FRONTEND_PORT = 3000
BACKEND_PORT = 8080


class BrowserBlocked(RuntimeError):
    pass


def local_url(url: str) -> bool:
    try:
        parsed = urlparse(url)
        return (parsed.scheme in ("http", "https", "ws", "wss")
                and parsed.hostname in ("localhost", "127.0.0.1", "::1")
                and parsed.username is None and parsed.password is None
                and parsed.port in (FRONTEND_PORT, BACKEND_PORT))
    except ValueError:
        return False


def check_path(path: str) -> str:
    if (not isinstance(path, str) or not path.startswith("/")
            or path.startswith("//") or "\\" in path or "\r" in path or "\n" in path):
        raise BrowserBlocked("BROWSER_PATH_INVALID")
    return path


CASE_KEYS = {"id", "path", "selector", "text", "title", "count", "css", "box",
             "viewport"}
BOX_KEYS = {"width", "height", "tolerance_px"}
CSS_PROPERTY = re.compile(r"[a-z-]{1,48}\Z")
CASE_ID = re.compile(r"[A-Za-z0-9_.-]{1,96}\Z")
MAX_CASES = 200


def _number(value, low, high):
    return (type(value) in (int, float) and low <= value <= high)


def check_case(case) -> dict:
    """Declarative browser case: data only, never code. Unknown keys deny."""
    if not isinstance(case, dict) or not set(case) <= CASE_KEYS:
        raise BrowserBlocked("BROWSER_CASE_INVALID")
    if not isinstance(case.get("id"), str) or not CASE_ID.fullmatch(case["id"]):
        raise BrowserBlocked("BROWSER_CASE_INVALID")
    check_path(case.get("path", "/"))
    selector = case.get("selector")
    if not isinstance(selector, str) or not selector or len(selector) > 512:
        raise BrowserBlocked("BROWSER_CASE_INVALID")
    for key in ("text", "title"):
        if key in case and (not isinstance(case[key], str) or not case[key]
                            or len(case[key]) > 512):
            raise BrowserBlocked("BROWSER_CASE_INVALID")
    if "count" in case and not (type(case["count"]) is int and 0 <= case["count"] <= 500):
        raise BrowserBlocked("BROWSER_CASE_INVALID")
    css = case.get("css", {})
    if (not isinstance(css, dict) or len(css) > 24
            or any(not isinstance(k, str) or not CSS_PROPERTY.fullmatch(k)
                   or not isinstance(v, str) or not v or len(v) > 128
                   for k, v in css.items())):
        raise BrowserBlocked("BROWSER_CASE_INVALID")
    box = case.get("box", {})
    if (not isinstance(box, dict) or not set(box) <= BOX_KEYS
            or any(k in box and not _number(box[k], 0, 10000) for k in ("width", "height"))
            or ("tolerance_px" in box and not _number(box["tolerance_px"], 0, 50))):
        raise BrowserBlocked("BROWSER_CASE_INVALID")
    if not any(k in case for k in ("text", "title", "count")) and not css and not box:
        # Visibility alone does not characterize behavior.
        raise BrowserBlocked("BROWSER_CASE_WITHOUT_ASSERTION")
    viewport = case.get("viewport")
    if viewport is not None and (not isinstance(viewport, dict)
                                 or set(viewport) != {"width", "height"}
                                 or not all(type(viewport[k]) is int and 200 <= viewport[k] <= 4000
                                            for k in viewport)):
        raise BrowserBlocked("BROWSER_CASE_INVALID")
    return case


def load_suite(root: Path, suite: str) -> list[dict]:
    """All *.json case files of a repository-relative suite directory."""
    rel = Path(suite)
    if rel.is_absolute() or ".." in rel.parts:
        raise BrowserBlocked("BROWSER_SUITE_INVALID")
    folder = root / rel
    if folder.is_symlink() or (folder.exists() and not folder.is_dir()):
        raise BrowserBlocked("BROWSER_SUITE_INVALID")
    cases, seen = [], set()
    for file in sorted(folder.glob("*.json")) if folder.is_dir() else []:
        if file.is_symlink() or not file.is_file():
            raise BrowserBlocked("BROWSER_SUITE_INVALID")
        try:
            data = json.loads(file.read_text("utf-8"))
        except (OSError, ValueError) as exc:
            raise BrowserBlocked("BROWSER_SUITE_INVALID") from exc
        items = data.get("cases") if isinstance(data, dict) else None
        if not isinstance(items, list) or not items or set(data) - {"cases", "covers"}:
            raise BrowserBlocked("BROWSER_SUITE_INVALID")
        for case in items:
            check_case(case)
            if case["id"] in seen:
                raise BrowserBlocked("BROWSER_SUITE_INVALID")
            seen.add(case["id"])
            cases.append(case)
    if len(cases) > MAX_CASES:
        raise BrowserBlocked("BROWSER_SUITE_INVALID")
    return cases


def assert_case(page, case: dict, timeout_ms: int) -> None:
    if case.get("viewport"):
        page.set_viewport_size(case["viewport"])
    page.goto(f"http://127.0.0.1:{FRONTEND_PORT}{case.get('path', '/')}",
              wait_until="domcontentloaded", timeout=timeout_ms)
    found = page.locator(case["selector"])
    if "count" in case:
        if case["count"] == 0:
            if found.count() != 0:
                raise BrowserBlocked("BROWSER_ASSERTION_FAILED:" + case["id"])
            return
        found.first.wait_for(state="attached", timeout=timeout_ms)
        if found.count() != case["count"]:
            raise BrowserBlocked("BROWSER_ASSERTION_FAILED:" + case["id"])
    item = found.first
    item.wait_for(state="visible", timeout=timeout_ms)
    _assert_loaded(page, case, item, timeout_ms)


def _assert_loaded(page, case: dict, item, timeout_ms: int) -> None:
    if "text" in case and case["text"] not in item.inner_text(timeout=timeout_ms):
        raise BrowserBlocked("BROWSER_ASSERTION_FAILED:" + case["id"])
    if "title" in case and case["title"] not in page.title():
        raise BrowserBlocked("BROWSER_ASSERTION_FAILED:" + case["id"])
    for prop, want in case.get("css", {}).items():
        got = item.evaluate("(el, p) => getComputedStyle(el).getPropertyValue(p)", prop)
        if str(got).strip() != want:
            raise BrowserBlocked("BROWSER_ASSERTION_FAILED:" + case["id"])
    box = case.get("box")
    if box:
        rect = item.bounding_box()
        tol = box.get("tolerance_px", 1)
        if rect is None or any(abs(rect[k] - box[k]) > tol for k in ("width", "height") if k in box):
            raise BrowserBlocked("BROWSER_ASSERTION_FAILED:" + case["id"])


# Applies the first candidate value that really changes the computed style;
# returns false if none does (the assertion then cannot be proven to matter).
MUTATION_JS = """(el, m) => {
  for (const [prop, candidates] of Object.entries(m)) {
    const before = getComputedStyle(el).getPropertyValue(prop);
    let changed = false;
    for (const value of candidates) {
      el.style.setProperty(prop, value, 'important');
      if (getComputedStyle(el).getPropertyValue(prop) !== before) { changed = true; break; }
    }
    if (!changed) return false;
  }
  return true;
}"""
CSS_CANDIDATES = ("777px", "rgb(1, 2, 3)", "none", "block", "inline", "hidden",
                  "0.37", "italic", "900", "100", "line-through", "uppercase",
                  "center", "right", "column", "wrap", "space-between", "3", "fixed")


def mutations(case: dict) -> list[dict]:
    """Mechanical in-page mutations of each asserted CSS value and box size.
    A discriminating case must fail under every one of them."""
    result = [{prop: list(CSS_CANDIDATES)} for prop in case.get("css", {})]
    box = case.get("box", {})
    for key in ("width", "height"):
        if key in box:
            target = f"{max(1, round(box[key] * 1.25 + 10 + 2 * box.get('tolerance_px', 1)))}px"
            result.append({key: [target],
                           "min-" + key: [target], "max-" + key: [target]})
    return result


def discriminates(page, case: dict, timeout_ms: int) -> None:
    """Re-run a passing case under each mutation; it must fail every time."""
    for mutation in mutations(case):
        page.goto(f"http://127.0.0.1:{FRONTEND_PORT}{case.get('path', '/')}",
                  wait_until="domcontentloaded", timeout=timeout_ms)
        item = page.locator(case["selector"]).first
        item.wait_for(state="visible", timeout=timeout_ms)
        if not item.evaluate(MUTATION_JS, mutation):
            raise BrowserBlocked("BROWSER_CASE_NOT_MUTABLE:" + case["id"])
        try:
            _assert_loaded(page, case, item, timeout_ms)
        except BrowserBlocked:
            continue
        raise BrowserBlocked("BROWSER_CASE_NOT_DISCRIMINATING:" + case["id"])


def available() -> None:
    """Fail closed before launching the app if the browser runtime is absent."""
    os.environ["PLAYWRIGHT_BROWSERS_PATH"] = BROWSERS_DIR
    try:
        from importlib.metadata import version
        if version("playwright") != PLAYWRIGHT_VERSION:
            raise BrowserBlocked("NAVEGADOR_NO_DISPONIBLE")
        from playwright.sync_api import sync_playwright
        with sync_playwright() as p:
            b = p.chromium.launch(headless=True)
            b.close()
    except BrowserBlocked:
        raise
    except Exception as exc:
        raise BrowserBlocked("NAVEGADOR_NO_DISPONIBLE") from exc


def _spawn(argv: list[str], root: Path) -> subprocess.Popen:
    try:
        # Neither browser assertions nor child-server logs receive secrets.
        return subprocess.Popen(argv, cwd=root, stdin=subprocess.DEVNULL,
                                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                start_new_session=True,
                                env={**os.environ, "CI": "true", "NEXT_TELEMETRY_DISABLED": "1"})
    except OSError as exc:
        raise BrowserBlocked("APP_NO_ARRANCA") from exc


def wait_local(port: int, proc: subprocess.Popen, seconds: int = 90) -> None:
    deadline = time.monotonic() + seconds
    while time.monotonic() < deadline:
        if proc.poll() is not None:
            raise BrowserBlocked("APP_NO_ARRANCA")
        try:
            with socket.create_connection(("127.0.0.1", port), timeout=0.5):
                return
        except OSError:
            time.sleep(0.3)
    raise BrowserBlocked("APP_NO_ARRANCA")


def _stop(proc: subprocess.Popen) -> None:
    try:
        os.killpg(proc.pid, signal.SIGKILL)
    except ProcessLookupError:
        pass
    try:
        proc.wait(timeout=5)
    except subprocess.TimeoutExpired:
        pass


APP_START_ATTEMPTS = 2


def verify(root: Path, **kwargs) -> None:
    """Retry only when the local app did not start (a known runner flake);
    never retry a failing browser assertion."""
    for attempt in range(1, APP_START_ATTEMPTS + 1):
        try:
            return _verify_once(root, **kwargs)
        except BrowserBlocked as exc:
            if str(exc) != "APP_NO_ARRANCA" or attempt == APP_START_ATTEMPTS:
                raise
            print("APP_NO_ARRANCA: reintento de arranque " + str(attempt + 1), file=sys.stderr)
            time.sleep(5)


def _verify_once(root: Path, *, path: str, selector: str, text: str | None,
           title: str | None, timeout_ms: int = 15000, cases: list | None = None,
           mutate: bool = False) -> None:
    path = check_path(path)
    from pilot.config import project_config as _project
    pom = _project.area_component("BACKEND", "maven")["build_file"]
    web = _project.area_component("FRONTEND", "npm")
    if not root.is_dir() or not (root / pom).is_file() \
            or not (root / web["build_file"]).is_file():
        raise BrowserBlocked("APP_NO_ARRANCA")
    if not selector or len(selector) > 512 or timeout_ms < 1000 or timeout_ms > 30000:
        raise BrowserBlocked("BROWSER_CASE_INVALID")
    available()
    running = []
    try:
        backend = _spawn(["mvn", "-B", "-q", "-f", pom,
                          "spring-boot:run", "-Dspring-boot.run.arguments=--server.address=127.0.0.1"],
                         root)
        running.append(backend)
        wait_local(BACKEND_PORT, backend)
        frontend = _spawn(["npm", "--prefix", web["root"], "run", "dev",
                           "--", "--hostname", "127.0.0.1", "--port", str(FRONTEND_PORT)], root)
        running.append(frontend)
        wait_local(FRONTEND_PORT, frontend)
        from playwright.sync_api import sync_playwright
        with sync_playwright() as p:
            try:
                browser = p.chromium.launch(headless=True)
            except Exception as exc:
                raise BrowserBlocked("NAVEGADOR_NO_DISPONIBLE") from exc
            try:
                context = browser.new_context(service_workers="block")
                # Network from Chromium never leaves the two loopback app ports.
                context.route("**/*", lambda route:
                              route.continue_() if local_url(route.request.url)
                              else route.abort("blockedbyclient"))
                context.route_web_socket("**/*", lambda ws:
                                         ws.connect_to_server() if local_url(ws.url)
                                         else ws.close())
                page = context.new_page()
                if cases is not None:
                    for case in cases:
                        assert_case(page, case, timeout_ms)
                        if mutate and (case.get("css") or case.get("box")):
                            discriminates(page, case, timeout_ms)
                    context.close()
                    return
                page.goto(f"http://127.0.0.1:{FRONTEND_PORT}{path}",
                          wait_until="domcontentloaded", timeout=timeout_ms)
                item = page.locator(selector).first
                item.wait_for(state="visible", timeout=timeout_ms)
                if text is not None and text not in item.inner_text(timeout=timeout_ms):
                    raise BrowserBlocked("BROWSER_ASSERTION_FAILED")
                if title is not None and title not in page.title():
                    raise BrowserBlocked("BROWSER_ASSERTION_FAILED")
                context.close()
            finally:
                browser.close()
    except BrowserBlocked:
        raise
    except Exception as exc:
        raise BrowserBlocked("BROWSER_ASSERTION_FAILED") from exc
    finally:
        for proc in reversed(running):
            _stop(proc)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path, default=Path("."))
    parser.add_argument("--path", default="/")
    parser.add_argument("--selector")
    parser.add_argument("--suite", help="repository-relative folder of *.json cases")
    parser.add_argument("--mutation-check", action="store_true",
                        help="each css/box case must fail under in-page mutations")
    parser.add_argument("--text")
    parser.add_argument("--title")
    parser.add_argument("--timeout-ms", type=int, default=15000)
    args = parser.parse_args()
    try:
        if args.suite is not None:
            cases = load_suite(args.root, args.suite)
            if not cases:
                print("BROWSER_SUITE_NO_CASES")
                return 0
            verify(args.root, path="/", selector="body", text=None, title=None,
                   timeout_ms=args.timeout_ms, cases=cases, mutate=args.mutation_check)
            print("BROWSER_SUITE_PASS:" + str(len(cases)))
            return 0
        if not args.selector:
            raise BrowserBlocked("BROWSER_CASE_INVALID")
        verify(args.root, path=args.path, selector=args.selector,
               text=args.text, title=args.title, timeout_ms=args.timeout_ms)
    except BrowserBlocked as exc:
        # The failing case id is safe to show: it is visible repository data.
        print(str(exc), file=sys.stderr)
        return 1
    print("BROWSER_VISIBLE_CHECK_PASS")
    return 0


if __name__ == "__main__":
    # Vendored command execution intentionally strips the runner's PATH.
    # Re-exec in the trusted pinned Python venv, not whichever python3 is
    # installed in /usr/local/bin or selected by a proposal.
    if not PYTHON_RUNTIME.is_file():
        print("NAVEGADOR_NO_DISPONIBLE", file=sys.stderr)
        raise SystemExit(1)
    try:
        if Path(sys.executable).absolute() != PYTHON_RUNTIME.absolute():
            os.execv(str(PYTHON_RUNTIME), [str(PYTHON_RUNTIME), __file__, *sys.argv[1:]])
    except OSError:
        print("NAVEGADOR_NO_DISPONIBLE", file=sys.stderr)
        raise SystemExit(1)
    raise SystemExit(main())
